"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"

import { cn } from "@/lib/utils"
import { useSound } from "./sound-provider"

// Clicky Checkbox — flat square with clean check state + tick sound

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Checkbox = React.forwardRef<
  HTMLButtonElement,
  WithClassName<CheckboxPrimitive.Root.Props>
>(({ className, onCheckedChange, ...props }, ref) => {
  const { playClick } = useSound()
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      ref={ref}
      className={cn(
        "peer inline-flex items-center justify-center h-4 w-4 shrink-0 rounded-sm",
        "border border-border bg-background",
        "transition-all duration-base ease-out",
        "active:translate-y-px",
        "hover:border-ring/50",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "data-checked:bg-primary data-indeterminate:bg-primary data-checked:border-[var(--primary-rim)] data-indeterminate:border-[var(--primary-rim)] data-checked:text-primary-foreground data-indeterminate:text-primary-foreground",
        "data-checked:shadow-[var(--shadow-tactile-control)] data-indeterminate:shadow-[var(--shadow-tactile-control)]",
        className
      )}
      onCheckedChange={(checked, eventDetails) => {
        playClick()
        onCheckedChange?.(checked, eventDetails)
      }}
      {...props}
    >
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
        <CheckIcon className="h-3.5 w-3.5 in-data-[indeterminate]:hidden" />
        <MinusIcon className="h-3.5 w-3.5 hidden in-data-[indeterminate]:block" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
})
Checkbox.displayName = "Checkbox"

export { Checkbox }

// "mingcute:check-line" and "mingcute:minimize-line" from MingCute,
// the icon library this system pairs with, drawn inline so the installed
// component loads no icon at runtime. [BD-1029]
function CheckIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="currentColor" d="M9.171 16.072L19.778 5.465c.409-.359 1.01-.404 1.414 0c.404.405.359 1.005 0 1.415L9.878 18.193c-.204.179-.429.293-.707.293s-.503-.114-.707-.293l-5.657-5.657c-.297-.339-.393-.8-.159-1.207c.34-.588 1.092-.629 1.574-.207Z"/>
    </svg>
  )
}
function MinusIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="currentColor" d="M4.741 12.966C3.643 12.672 3.796 11.079 5 11h14c.543.036 1 .428 1 1s-.457.964-1 1H5Z"/>
    </svg>
  )
}
